// The handbook pages LiftOff ships, with every revision a team may have copied (generated by scripts/build-catalog.mjs from
// src/handbook/base/*.md; the JSON is bundled into the CLI, so nothing is read from the plugin folder at run time).
import data from "./catalog.json" with { type: "json" };

export interface Revision { rev: number; since: string; base: string; text: string }
export interface CatalogPage { id: string; type: "practice" | "convention"; status?: "stub"; revisions: Revision[] }

export const CATALOG: CatalogPage[] = (data as { pages: CatalogPage[] }).pages;
export const catalogIds = (): string[] => CATALOG.map((p) => p.id);
export const catalogPage = (id: string): CatalogPage | undefined => CATALOG.find((p) => p.id === id);
export const latest = (page: CatalogPage): Revision => page.revisions[page.revisions.length - 1]!;
// The revision a team's copy started from, when it is still kept (`base` is the fingerprint the copy carries).
export const revisionOf = (page: CatalogPage, base: string): Revision | undefined => page.revisions.find((r) => r.base === base);
